const STANDARD_REMIX_DEFAULTS = {
  artist: 'random',
  mixTitle: '',
  useTrax: false,
  selectedFolders: [],
  videoFilter: 'look_hard_bw_street_doc',
  filterIntensity: 0.8,
  enableOverlay: false,
  overlayEffect: '',
  topLogo: 'ue_barcode_white.png',
  endLogo: 'ue_square.png',
  useArtistImage: false,
  endTextOverlay: '',
  count: 1,
};
// Build a render recipe from a draft-shaped settings object (or the house
// defaults). Single source of truth for recipe construction.
function buildRemixRecipe(settings = STANDARD_REMIX_DEFAULTS, sourceFolders) {
  const s = { ...STANDARD_REMIX_DEFAULTS, ...settings };
  const folders = Array.isArray(sourceFolders) ? sourceFolders : s.selectedFolders;
  return {
    sourceFolders: folders,
    output: { width: 720, height: 720, fps: 30, format: 'mp4', durationSeconds: 30 },
    artist: s.artist === 'random' ? null : s.artist,
    mixTitle: s.mixTitle || null,
    useTrax: s.useTrax,
    filter: s.videoFilter && s.videoFilter !== 'random'
      ? { key: s.videoFilter, intensity: s.filterIntensity }
      : { intensity: s.filterIntensity },
    overlay: s.enableOverlay && s.overlayEffect
      ? { enabled: true, effect: s.overlayEffect }
      : { enabled: false },
    logos: { top: s.topLogo || null, end: s.endLogo || null },
    useArtistImage: s.useArtistImage,
    endCard: s.endTextOverlay ? { text: s.endTextOverlay } : null,
  };
}
function parseBriefSuggestedPost(raw) {
  if (!raw) return '';
  let collecting = false;
  const out = [];
  for (const ln of String(raw).split('\n')) {
    const t = ln.trim();
    if (!t) continue;
    const isLabel = CB_SUMMARY_LABELS.find((L) => t.toLowerCase().startsWith(`${L.toLowerCase()}:`));
    if (isLabel) {
      if (collecting) break; // next section reached
      if (isLabel === 'Suggested Post') {
        collecting = true;
        const after = t.slice(t.indexOf(':') + 1).trim();
        if (after) out.push(after);
      }
      continue;
    }
    if (collecting) out.push(t);
  }
  return out.join(' ').replace(/\s+/g, ' ').trim();
}

function sanitizeVideoRemixFolderPreview(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '-')
    .replace(/[^a-z0-9_-]+/g, '')
    .replace(/-+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

function formatVideoRemixBytes(bytes) {
  const size = Number(bytes || 0);
  if (!Number.isFinite(size) || size <= 0) return '0 B';
  if (size >= 1024 * 1024 * 1024) return `${(size / (1024 * 1024 * 1024)).toFixed(1)} GB`;
  if (size >= 1024 * 1024) return `${(size / (1024 * 1024)).toFixed(1)} MB`;
  if (size >= 1024) return `${(size / 1024).toFixed(1)} KB`;
  return `${size} B`;
}

function safeDownloadName(value, fallback = 'download') {
  return String(value || fallback)
    .replace(/[^a-z0-9._-]+/gi, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 96) || fallback;
}

async function downloadBrowserAsset(href, filename = 'download', { preferNativeShare = false, mimeType = '', fetchHeaders = null } = {}) {
  if (!href || typeof window === 'undefined') return;
  const cleanFilename = safeDownloadName(filename);
  let blobUrl = null;
  try {
    // fetchHeaders carries auth for same-origin proxy endpoints (e.g. the
    // remix-download stream). Same-origin requests ignore `mode:cors` harmlessly.
    const res = await fetch(href, { mode: 'cors', cache: 'force-cache', ...(fetchHeaders ? { headers: fetchHeaders } : {}) });
    if (!res.ok) throw new Error(String(res.status));
    const blob = await res.blob();
    const typedBlob = mimeType && blob.type !== mimeType ? new Blob([blob], { type: mimeType }) : blob;

    if (preferNativeShare && typeof File === 'function' && navigator?.share && navigator?.canShare) {
      const file = new File([typedBlob], cleanFilename, { type: typedBlob.type || mimeType || 'application/octet-stream' });
      if (navigator.canShare({ files: [file] })) {
        try {
          await navigator.share({ files: [file], title: cleanFilename });
          return;
        } catch (shareErr) {
          if (shareErr?.name === 'AbortError') return;
        }
      }
    }

    blobUrl = URL.createObjectURL(typedBlob);
    const a = document.createElement('a');
    a.href = blobUrl;
    a.download = cleanFilename;
    a.rel = 'noopener';
    document.body.appendChild(a);
    a.click();
    a.remove();
  } catch {
    const a = document.createElement('a');
    a.href = href;
    a.download = cleanFilename;
    a.target = '_blank';
    a.rel = 'noopener noreferrer';
    document.body.appendChild(a);
    a.click();
    a.remove();
  } finally {
    if (blobUrl) setTimeout(() => URL.revokeObjectURL(blobUrl), 4000);
  }
}

// Render a video's first frame as a cheap thumbnail without generating a poster
// image: the `#t=0.1` media fragment tells the browser to paint ~0.1s in (the
// first real frame) instead of a black frame, using only a metadata range
// request. Fragment sits after any query string, so signed URLs are fine.
function firstFrameThumbSrc(url) {
  if (!url) return undefined;
  return /#t=/.test(url) ? url : `${url}#t=0.1`;
}

function videoRemixPendingStorageKey(clientId) {
  return `${VIDEO_REMIX_PENDING_STORAGE_PREFIX}:${clientId || 'self'}`;
}

function readVideoRemixPendingJob(clientId) {
  if (typeof window === 'undefined' || !clientId) return null;
  try {
    const raw = window.localStorage.getItem(videoRemixPendingStorageKey(clientId));
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function writeVideoRemixPendingJob(clientId, value) {
  if (typeof window === 'undefined' || !clientId) return;
  try {
    if (value) window.localStorage.setItem(videoRemixPendingStorageKey(clientId), JSON.stringify(value));
    else window.localStorage.removeItem(videoRemixPendingStorageKey(clientId));
  } catch {
    /* localStorage is an optimization only */
  }
}

function normalizeVideoRemixFolderDetails(rawFolders) {
  return (Array.isArray(rawFolders) ? rawFolders : [])
    .map((item) => {
      if (typeof item === 'string') return { name: item, displayName: item, count: null, type: 'root' };
      return {
        name: String(item?.name || ''),
        displayName: String(item?.displayName || item?.name || ''),
        count: Number.isFinite(Number(item?.count)) ? Number(item.count) : null,
        type: item?.type || 'root',
      };
    })
    .filter((item) => item.name);
}

function uploadVideoRemixFileToSignedUrl({ file, upload, onProgress }) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open(upload.method || 'PUT', upload.uploadUrl);
    xhr.setRequestHeader('Content-Type', upload.contentType || file.type || 'application/octet-stream');
    xhr.upload.onprogress = (event) => {
      if (event.lengthComputable && typeof onProgress === 'function') {
        onProgress(Math.round((event.loaded / event.total) * 100));
      }
    };
    xhr.onload = () => {
      if (xhr.status >= 200 && xhr.status < 300) resolve();
      else reject(new Error(`Upload failed (${xhr.status})`));
    };
    xhr.onerror = () => reject(new Error('Upload failed before storage accepted the file.'));
    xhr.send(file);
  });
}

function sanitizeBriefHtmlForStandalone(rawHtml) {
  const html = String(rawHtml || '');
  if (!html || typeof window === 'undefined' || typeof window.DOMParser !== 'function') return html;
  try {
    const doc = new window.DOMParser().parseFromString(html, 'text/html');
    doc.querySelectorAll('script').forEach((node) => node.remove());
    doc.querySelectorAll('*').forEach((node) => {
      for (const attr of Array.from(node.attributes || [])) {
        if (/^on/i.test(attr.name)) node.removeAttribute(attr.name);
      }
    });
    return `<!doctype html>\n${doc.documentElement.outerHTML}`;
  } catch {
    return html
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/\son[a-z]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, '');
  }
}

